  persist(
    (set) => ({
      isLoggedIn: false,
      setLoggedIn: (value) => set({ isLoggedIn: value }),
      logout: () => set({ isLoggedIn: false }),
    }),
    { name: 'auth-ui-storage', storage: createJSONStorage(() => mmkvStorage) }
  )
